function marcarFecha() {
  const hoja = SpreadsheetApp.getActiveSheet();
  hoja.getRange('A1').setValue(new Date());
}

function onEdit(e) {
  const rango = e.range;
  if (rango.getColumn() === 2) {
    rango.offset(0, 1).setValue(new Date());
  }
}

const hoja = SpreadsheetApp.getActiveSheet();
const datos = hoja.getRange('A2:C10').getValues();

const filtrados = datos.filter((fila) => fila[2] > 100);
hoja.getRange(2, 5, filtrados.length, 3).setValues(filtrados);

/**
 * Convierte un precio a su valor con IVA.
 * @param {number} precio El precio sin IVA.
 * @return {number} El precio con IVA incluido.
 * @customfunction
 */
function CON_IVA(precio) {
  return precio * 1.21;
}
